import { Component } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { WorkOrdersService } from '../../services/work-orders.service';
import { LookupsService } from 'src/app/services/lookups.service';
import { FormControl, FormGroup, Validators } from '@angular/forms';
import { TranslateService } from '@ngx-translate/core';
import { DatePipe } from '@angular/common';

// import pdfMake from 'pdfmake/build/pdfmake';
// import pdfFonts from 'pdfmake/build/vfs_fonts';

import * as pdfMake from "pdfmake/build/pdfmake";
import * as pdfFonts from 'pdfmake/build/vfs_fonts';
// import { PdfMakeFontService } from 'src/app/services/pdf-make-font.service';

// (<any>pdfMake).addVirtualFileSystem(pdfFonts);
(pdfMake as any).vfs = (pdfFonts as any).pdfMake.vfs;


@Component({
  selector: 'app-view-order',
  templateUrl: './view-order.component.html',
  styleUrls: ['./view-order.component.scss'],
  providers: [DatePipe]
})
export class ViewOrderComponent {
  ngOnInit() {
    this.getOrderById(this.orderId);

    this.getworkType()
    this.getBuilding()
    this.getEqipment()
    this.getSource()
    this.getReport()
    this.getDepartment()
    this.getOrderMaterial()
    this.getOrderParts()
    this.getStatus()

  }

  constructor(
    private _activateRoute: ActivatedRoute,
    private _WorkOrdersService: WorkOrdersService,
    private _LookupsService: LookupsService,
    public translate: TranslateService,
    // private fontService: PdfMakeFontService,
    private datePipe: DatePipe

  ) {
    this.orderId = this._activateRoute.snapshot.paramMap.get('id')

    const pdfMakeTyped = pdfMake as any;
    const pdfFontsTyped = pdfFonts as any;
    (pdfMake as any).vfs = (pdfFonts as any).pdfMake.vfs;
    // ✅ 1. Load core fonts first
    // (pdfMake as any).vfs = pdfFontsTyped.pdfMake.vfs;

    // (pdfMake as any).vfs["Amiri-Regular.ttf"] = '';
    (pdfMake as any).vfs["Amiri-Regular.ttf"] = "...";


    // Add to font list
    (pdfMake as any).fonts = {
      ...((pdfMake as any).fonts || {}),
      ArabicFont: {
        normal: 'Amiri-Regular.ttf',
        bold: 'Amiri-Regular.ttf',
        italics: 'Amiri-Regular.ttf',
        bolditalics: 'Amiri-Regular.ttf'
      },
      Roboto: {
        normal: 'Roboto-Regular.ttf',
        bold: 'Roboto-Medium.ttf',
        italics: 'Roboto-Italic.ttf',
        bolditalics: 'Roboto-MediumItalic.ttf'
      },
    };
  }


  orderId: any;
  currentOrder: any
  workType: any
  building: any
  equipment: any
  source: any
  report: any
  department: any
  currentLang = localStorage.getItem('lang')



  hide: boolean = true;
  confirmHide: boolean = true;
  hideRequiredMarker: boolean = true;

  materialTableData: any;
  spareTableData: any;

  status: any
  statusId: any
  isHold: boolean = false

  orderForm = new FormGroup(
    {
      start_date: new FormControl({ value: '', disabled: true }, [Validators.required]),
      department: new FormControl({ value: '', disabled: true }, [Validators.required]),
      engineer: new FormControl({ value: '', disabled: true },),
      technician: new FormControl({ value: '', disabled: true },),
      work_type: new FormControl({ value: '', disabled: true }, [Validators.required]),
      building: new FormControl({ value: '', disabled: true }, [Validators.required]),
      floor_no: new FormControl({ value: '', disabled: true }, [Validators.required]),
      room_no: new FormControl({ value: '', disabled: true }, [Validators.required]),
      source: new FormControl({ value: '', disabled: true }, [Validators.required]),
      customer_name: new FormControl({ value: '', disabled: true }, [Validators.required]),
      customer_phone: new FormControl({ value: '', disabled: true }, [Validators.required]),
      equipment: new FormControl({ value: '', disabled: true }, [Validators.required]),
      description: new FormControl({ value: '', disabled: true }, [Validators.required]),
      priority: new FormControl({ value: '', disabled: true }, [Validators.required]),
      type: new FormControl({ value: '', disabled: true },),
      // {value: '', disabled: true}
    }
  );

  updateOrderForm = new FormGroup({
    status: new FormControl({ value: '', disabled: true }, [Validators.required]),
    technician_report: new FormControl({ value: '', disabled: true }, [Validators.required]),
    // holding_reason: new FormControl(null),

    // used_items_descriptions: new FormControl(null,[Validators.required]),
  })


  getOrderById(id: number) {
    this._WorkOrdersService.getOrder(id).subscribe(
      (res) => {
        this.currentOrder = res.data
        // console.log(this.currentOrder.work_type.id)
        if (this.currentOrder.status.id == 4) {
          this.isHold = true;
          (this.updateOrderForm as FormGroup).addControl('holding_reason', new FormControl({ value: '', disabled: true }))
          this.updateOrderForm.patchValue({ holding_reason: this.currentOrder.holding_reason } as any);

        }
        this.orderForm.patchValue({
          department: this.currentOrder?.department.id,
          floor_no: this.currentOrder?.floor_no,
          room_no: this.currentOrder?.room_no,
          work_type: this.currentOrder?.work_type.id,
          building: this.currentOrder?.building.id,
          engineer: this.currentOrder?.engineer?.name,
          technician: this.currentOrder?.technician?.name,
          customer_name: this.currentOrder?.customer_name,
          customer_phone: this.currentOrder?.customer_phone,
          equipment: this.currentOrder?.equipment.id,
          source: this.currentOrder?.source.id,
          description: this.currentOrder?.description,
          start_date: this.currentOrder?.start_date,


        })
        this.updateOrderForm.patchValue({
          status: this.currentOrder?.status.name,
          technician_report: this.currentOrder?.technician_report,

          // holding_reason: this.currentOrder?.holding_reason,
        })
      }
    )
  }

  getOrderMaterial() {
    this._WorkOrdersService.getMaterialByOrderId(this.orderId).subscribe(
      (res) => {
        this.materialTableData = res.data
      }
    )
  }
  getOrderParts() {
    this._WorkOrdersService.getPartsByOrderId(this.orderId).subscribe(
      (res) => {
        this.spareTableData = res.data
      }
    )
  }

  // Start Lookups 

  getworkType() {
    this._LookupsService.getWork_type().subscribe(
      (res) => {
        this.workType = res.data
      }
    )
  }
  getBuilding() {
    this._LookupsService.getbuilding().subscribe(
      (res) => {
        this.building = res.data
      }
    )
  }
  getSource() {
    this._LookupsService.getSource().subscribe(
      (res) => {
        this.source = res.data
      }
    )
  }
  getEqipment() {
    this._LookupsService.getEquipment().subscribe(
      (res) => {
        this.equipment = res.data
      }
    )
  }
  getReport() {
    this._LookupsService.getReport().subscribe(
      (res) => {
        this.report = res.data
      }
    )
  }
  getDepartment() {
    this._LookupsService.getDepartment().subscribe(
      (res) => {
        this.department = res.data
      }
    )
  }
  getStatus() {
    this._LookupsService.getStatus().subscribe(
      (res) => {
        this.status = res.data
      }
    )
  }


  // 
  generateInvoice() {

    const logoBase64: any = 'data:image/png;base64,'

    const logo2: any = 'data:image/png;base64,'

    const data: any = {
      start_date: this.datePipe.transform(this.currentOrder?.start_date, 'dd-MM-yyyy'),
      department: this.currentOrder?.department.name,
      engineer: this.currentOrder?.engineer?.name,
      technician: this.currentOrder?.technician?.name,
      work_type: this.currentOrder?.work_type.name,
      building: this.currentOrder?.building.name,
      floor_no: this.currentOrder?.floor_no,
      room_no: this.currentOrder?.room_no,
      customer_name: this.currentOrder?.customer_name,
      customer_phone: this.currentOrder?.customer_phone,
      equipment: this.currentOrder?.equipment.name,
      source: this.currentOrder?.source.name,
      status: this.currentOrder?.status.name,
      holding_reason: this.currentOrder?.holding_reason,
      description: this.currentOrder?.description,
      technician_report: this.currentOrder?.technician_report,
    };

    // Convert into rows: [key1, value1, key2, value2]
    const keys = Object.keys(data);
    const rows = [];

    for (let i = 0; i < keys.length; i += 2) {
      const key1 = keys[i];
      const key2 = keys[i + 1];

      rows.push([
        { text: key1, bold: true, style: 'tableHeader' },
        data[key1] ?? '',
        { text: key2 ?? '', bold: true, style: 'tableHeader' },
        data[key2] ?? ''
      ]);
    }
    // Table 2

    const tableBody2: any = [
      // 🧠 Table Header
      [
        { text: 'Name', style: 'tableHeader' },
        { text: 'Quantity', style: 'tableHeader' },
        { text: 'Description', style: 'tableHeader' }
      ],
    ];

    // 🗂 Table Rows
    this.materialTableData.forEach((item: any) => {
      tableBody2.push([
        item.name,
        item.quantity.toString(),
        item.description
      ]);
    })
    // Table 3: 

    const tableBody3: any = [
      // 🧠 Table Header
      [
        { text: 'Name', style: 'tableHeader' },
        { text: 'Quantity', style: 'tableHeader' },
        { text: 'Description', style: 'tableHeader' }
      ],
    ];

    // 🗂 Table Rows
    this.spareTableData.forEach((item: any) => {
      tableBody3.push([
        item.name,
        item.quantity.toString(),
        item.description
      ]);
    })

    const docDefinition: any = {
      content: [
        // Page Header
        {
          columns: [
            {
              image: logoBase64,
              width: 70,
              margin: [0, 0, 0, 60]
            },
            {
              stack: [
                { text: `${this.translate.instant('orders.orders')}`, style: 'title', alignment: 'center' },
                { text: `# ${this.currentOrder?.number}`, alignment: 'center' },
                { text: 'Date: ' + this.datePipe.transform(new Date(), 'dd-MM-yyyy'), alignment: 'center' }
              ]
            },
            {
              image: logo2,
              width: 100,
              margin: [0, 0, 0, 60]
            },
          ]
        },

        // table1
        { text: `${this.translate.instant('orders.orderReport')}`, style: 'title' },
        {
          table: {
            widths: ['auto', '*', 'auto', '*'],
            body: rows
          },
          layout: 'lightHorizontalLines'
        },
        // table2

        { text: `${this.translate.instant('orders.update.material')}`, style: 'title', margin: [0, 20, 0, 10] },
        {
          table: {
            widths: ['auto', 'auto', '*'],
            body: tableBody2
          },
          layout: 'lightHorizontalLines'
        },
        // table3

        { text: `${this.translate.instant('orders.update.parts')}`, style: 'title', font: 'ArabicFont', margin: [0, 20, 0, 10] },
        {
          table: {
            widths: ['auto', 'auto', '*'],
            body: tableBody3
          },
          layout: 'lightHorizontalLines'
        }
      ],

      styles: {
        title: {
          fontSize: 16,
          bold: true,
          margin: [0, 0, 0, 10]
        },
        tableHeader: {
          bold: true,
          fontSize: 12,
          fillColor: '#eeeeee'
        },
        defaultStyle: {
          font: 'ArabicFont',
          alignment: 'right'
        }
      }
    };
    pdfMake.createPdf(docDefinition).open();
  }
}
